(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LC_1RC1LD_0LB0RC_1LB0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB1LC_1RC1LD_0LB0RC_1LB0LA /\
