    rewrite (srun_sound tm false true chz_1RB1LC_1RC1LD_0LB0RC_1LB0LA Z0_1RB1LC_1RC1LD_0LB0RC_1LB0LA Z1_1RB1LC_1RC1LD_0LB0RC_1LB0LA 0 2
