    f_equal. exact HB.
  - destruct (gp_1RB1LC_1RC1LD_0LB0RC_1LB0LA p j' q0 E) as (HA & HB).
    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LC_1RC1LD_0LB0RC_1LB0LA P0_1RB1LC_1RC1LD_0LB0RC_1LB0LA P1_1RB1LC_1RC1LD_0LB0RC_1LB0LA 4 6
