Lemma geo_1RB1LC_1RC1LD_0LB0RC_1LB0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_1RC1LD_0LB0RC_1LB0LA) = lift (Cc (Pos.succ p)).
