  assert (HD : cden [] [] j B1_1RB1LC_1RC1LD_0LB0RC_1LB0LA
             = (StC, (rep [S0;S0] (S j) ++ [S1], S0, [S1;S0;S1]))).
  { unfold cden, B1_1RB1LC_1RC1LD_0LB0RC_1LB0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S0;S1]))).
  { unfold Cc_1RB1LC_1RC1LD_0LB0RC_1LB0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LC_1RC1LD_0LB0RC_1LB0LA. reflexivity.
