(** ** The lap *)

Lemma lap_1RB1LC_1RC1LD_0LB0RC_1LB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
