  - destruct (lapi_1RB1LC_1RC1LD_0LB0RC_1LB0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC1LD_0LB0RC_1LB0LA B0_1RB1LC_1RC1LD_0LB0RC_1LB0LA B1_1RB1LC_1RC1LD_0LB0RC_1LB0LA 4 6 p j' [] []).
    + exact run_ovf_1RB1LC_1RC1LD_0LB0RC_1LB0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1RC1LD_0LB0RC_1LB0LA p j' E).
    + exact (geo_1RB1LC_1RC1LD_0LB0RC_1LB0LA p j' E).
    + lia.
