(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LC_1RC1LD_0LB0RC_1LB0LA : existsb (fun tg => cfires tm_1RB1LC_1RC1LD_0LB0RC_1LB0LA c0 16 tg) pins_1RB1LC_1RC1LD_0LB0RC_1LB0LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_1RC1LD_0LB0RC_1LB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_1RC1LD_0LB0RC_1LB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_1RC1LD_0LB0RC_1LB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_1RC1LD_0LB0RC_1LB0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_1RC1LD_0LB0RC_1LB0LA : forall t, ~ In t pins_1RB1LC_1RC1LD_0LB0RC_1LB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_1RC1LD_0LB0RC_1LB0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_1RC1LD_0LB0RC_1LB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_1RC1LD_0LB0RC_1LB0LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_1RC1LD_0LB0RC_1LB0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_1RC1LD_0LB0RC_1LB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LC_1RC1LD_0LB0RC_1LB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtr_1RB1LC_1RC1LD_0LB0RC_1LB0LA : NonHalt tm_1RB1LC_1RC1LD_0LB0RC_1LB0LA /\ QHBoundTr 32779478 tm_1RB1LC_1RC1LD_0LB0RC_1LB0LA /\ QuasiHaltsTr tm_1RB1LC_1RC1LD_0LB0RC_1LB0LA.
Proof.
  apply (lap_qh_stage tm_1RB1LC_1RC1LD_0LB0RC_1LB0LA pins_1RB1LC_1RC1LD_0LB0RC_1LB0LA Cc 1 16 32779478).
  - exact bootq_1RB1LC_1RC1LD_0LB0RC_1LB0LA.
  - intros p _. apply lap_1RB1LC_1RC1LD_0LB0RC_1LB0LA.
  - intros t Ht p _. apply fire_1RB1LC_1RC1LD_0LB0RC_1LB0LA. exact Ht.
  - exact wit_1RB1LC_1RC1LD_0LB0RC_1LB0LA.
  - apply qcleb_QE_06. reflexivity.
Qed.

