Lemma fireo_1RB1LD_1LC1RA_0RB0LC_0LB0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LC1RA_0RB0LC_0LB0RA = Some t ->
