    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LD_1LC1RA_0RB0LC_0RB0RD P0_1RB1LD_1LC1RA_0RB0LC_0RB0RD P1_1RB1LD_1LC1RA_0RB0LC_0RB0RD 4 6
