(** 1RB1LD_1LC1RA_0RB0LC_1LC1RD *)
(** 1RB1LD_1LC1RA_0RB0LC_1LC1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LD_1LC1RA_0RB0LC_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StD end.

(** Its mirror 1LB1RD_1RC1LA_0LB0RC_1RC1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LD_1LC1RA_0RB0LC_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LD_1LC1RA_0RB0LC_1LC1RD : list Instr := [(StA, S1); (StD, S0); (StD, S1)].
Definition tmw_1RB1LD_1LC1RA_0RB0LC_1LC1RD : TM := tm_wrap_trs tmm_1RB1LD_1LC1RA_0RB0LC_1LC1RD pins_1RB1LD_1LC1RA_0RB0LC_1LC1RD.
Local Notation tm := tmw_1RB1LD_1LC1RA_0RB0LC_1LC1RD.

Lemma mirror_ok_1RB1LD_1LC1RA_0RB0LC_1LC1RD : mirror_tm tm_1RB1LD_1LC1RA_0RB0LC_1LC1RD = tmm_1RB1LD_1LC1RA_0RB0LC_1LC1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LD_1LC1RA_0RB0LC_1LC1RD (p : positive) : cconf := (StC, (Ap_Alph_00_10_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1LD_1LC1RA_0RB0LC_1LC1RD.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LD_1LC1RA_0RB0LC_1LC1RD : sconf := mkC StC (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LD_1LC1RA_0RB0LC_1LC1RD : sconf := mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1LD_1LC1RA_0RB0LC_1LC1RD : list lstep := [SWin 2].

Lemma run_z_1RB1LD_1LC1RA_0RB0LC_1LC1RD : srun tm false true chz_1RB1LD_1LC1RA_0RB0LC_1LC1RD Z0_1RB1LD_1LC1RA_0RB0LC_1LC1RD = Some (Z1_1RB1LD_1LC1RA_0RB0LC_1LC1RD, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
