Lemma fireo_1RB1LD_1LC1RA_0RB0LC_1RA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LC1RA_0RB0LC_1RA1RD = Some t ->
